1	import { privateMatch, rulesPresets, type ValidationResult } from "./rules.js";
2	import {
3	  ENGAGEMENT_RANGE_TILES,
4	  SIGHT_RADIUS_TILES,
5	  travelTargets,
6	  WORLD_STEPS_PER_SECOND,
7	  type ShipTuning,
8	} from "./sailing.js";
9	import { insideIsland, isNavigable, Terrain, terrainAt, type SeaMapDefinition } from "./seaMap.js";
10	
11	const UNREACHABLE = Number.MAX_SAFE_INTEGER;
12	
13	/** No island rectangle may be larger than this many tiles on a side: the slice's islands are small (§18). */
14	export const MAX_ISLAND_SIDE_TILES = 16;
15	
16	/** The slice sea is compact (§3's travel times at three tiles a second): at most this many tiles on a side. */
17	export const MAX_SEA_SIDE_TILES = 112;
18	
19	/**
20	 * Octile path costs for one tile step, in sub-units: straight is a tile's side, diagonal its side times √2, rounded to
21	 * the nearest integer by an integer square root (no floating-point `Math.sqrt` in the pure packages). For 256
22	 * sub-units a tile, 256 and 362.
23	 */
24	export function octileStepCosts(subUnitsPerTile: number): { readonly straight: number; readonly diagonal: number } {
25	  const square = 2 * subUnitsPerTile * subUnitsPerTile;
26	  let root = 0;
27	  while ((root + 1) * (root + 1) <= square) root++;
28	  // Round half up: √square ≥ root + ½ exactly when square − root² > root.
29	  return { straight: subUnitsPerTile, diagonal: square - root * root > root ? root + 1 : root };
30	}
31	
32	/**
33	 * Shortest sea-path cost in sub-units from one tile to every tile, over navigable tiles, moving in eight directions.
34	 * A diagonal step needs both tiles beside it free, since a hull cannot squeeze between two blocked corners. Tiles
35	 * marked in `blocked` (row-major, 1 for blocked) count as obstacles too.
36	 */
37	export function seaPathCosts(map: SeaMapDefinition, fromX: number, fromY: number, blocked?: Uint8Array): Float64Array {
38	  const width = map.widthTiles;
39	  const costs = new Float64Array(width * map.heightTiles).fill(UNREACHABLE);
40	  const open = (x: number, y: number) => isNavigable(map, x, y) && blocked?.[y * width + x] !== 1;
41	  if (!open(fromX, fromY)) return costs;
42	  const step = octileStepCosts(map.subUnitsPerTile);
43	  const heap = new MinHeap();
44	  const start = fromY * width + fromX;
45	  costs[start] = 0;
46	  heap.push(0, start);
47	  while (heap.size > 0) {
48	    const [cost, index] = heap.pop();
49	    if (cost > costs[index]!) continue;
50	    const x = index % width;
51	    const y = (index - x) / width;
52	    for (let dy = -1; dy <= 1; dy++) {
53	      for (let dx = -1; dx <= 1; dx++) {
54	        if (dx === 0 && dy === 0) continue;
55	        const nx = x + dx;
56	        const ny = y + dy;
57	        if (!open(nx, ny)) continue;
58	        const diagonal = dx !== 0 && dy !== 0;
59	        if (diagonal && (!open(x + dx, y) || !open(x, y + dy))) continue;
60	        const next = cost + (diagonal ? step.diagonal : step.straight);
61	        const target = ny * width + nx;
62	        if (next < costs[target]!) {
63	          costs[target] = next;
64	          heap.push(next, target);
65	        }
66	      }
67	    }
68	  }
69	  return costs;
70	}
71	
72	/** Seconds at full speed for a path cost, rounded down to milliseconds. */
73	export function travelSeconds(cost: number, tuning: ShipTuning): number {
74	  return Math.floor((cost * 1000) / (tuning.maxSpeed * WORLD_STEPS_PER_SECOND)) / 1000;
75	}
76	
77	export interface PointOfInterest {
78	  readonly label: string;
79	  readonly tileX: number;
80	  readonly tileY: number;
81	}
82	
83	export interface SeaMapReport {
84	  /** Each island's nearest other island by sea, dock to dock. */
85	  readonly nearestIsland: readonly { island: string; nearest: string; seconds: number }[];
86	  /** The longest shortest trip between any two docks or spawn slots. */
87	  readonly longestCrossing: { from: string; to: string; seconds: number };
88	  /** Each spawn slot's nearest dock. */
89	  readonly firstDock: readonly { slot: number; dock: string; seconds: number }[];
90	  /** The largest squared distance, in tiles, from a navigable tile to the nearest land, shoal or dock tile. */
91	  readonly largestObstacleDistanceSquared: number;
92	  /** The share of the map's tiles that are open sea, from 0 to 1. */
93	  readonly openSeaShare: number;
94	  /** For each pair of docks on different islands, how close one of its shortest routes comes to the hub (squared tiles). */
95	  readonly hubApproach: readonly { from: string; to: string; squaredTiles: number }[];
96	}
97	
98	export interface SeaMapRules {
99	  readonly islands: number;
100	  readonly spawnSlots: number;
101	}
102	
103	export const sliceSeaRules: SeaMapRules = { islands: rulesPresets.slice.islands, spawnSlots: privateMatch.maxPlayers };
104	
105	/**
106	 * The squared distance, in tiles from tile centre to tile centre, from each tile to the nearest land, shoal or dock tile
107	 * (row-major). The map edge is not an obstacle. The search stops at the sight radius: a tile with nothing that close
108	 * reads UNREACHABLE.
109	 */
110	export function obstacleDistancesSquared(map: SeaMapDefinition): Float64Array {
111	  const width = map.widthTiles;
112	  const height = map.heightTiles;
113	  const distances = new Float64Array(width * height).fill(UNREACHABLE);
114	  const obstacle = (x: number, y: number) => {
115	    const kind = terrainAt(map, x, y);
116	    return kind !== undefined && kind !== Terrain.Sea;
117	  };
118	  for (let tileY = 0; tileY < height; tileY++) {
119	    for (let tileX = 0; tileX < width; tileX++) {
120	      let best = UNREACHABLE;
121	      // Ring by ring outwards: every tile of ring r is at least r away, so once r² reaches the best, nothing beats it.
122	      for (let ring = 0; ring <= SIGHT_RADIUS_TILES && ring * ring < best; ring++) {
123	        for (let dy = -ring; dy <= ring; dy++) {
124	          // The ring's top and bottom rows in full; between them, only its two ends.
125	          const step = Math.abs(dy) === ring ? 1 : 2 * ring;
126	          for (let dx = -ring; dx <= ring; dx += step) {
127	            if (obstacle(tileX + dx, tileY + dy)) best = Math.min(best, dx * dx + dy * dy);
128	          }
129	        }
130	      }
131	      distances[tileY * width + tileX] = best;
132	    }
133	  }
134	  return distances;
135	}
136	
137	/**
138	 * Whether a tile lies in the hub's disc: its centre within half the sight radius of the hub tile's centre, so the
139	 * centres of any two tiles in the disc are within sight of each other.
140	 */
141	export function inHubDisc(map: SeaMapDefinition, tileX: number, tileY: number): boolean {
142	  const dx = 2 * (tileX - map.hub.tileX);
143	  const dy = 2 * (tileY - map.hub.tileY);
144	  return dx * dx + dy * dy <= SIGHT_RADIUS_TILES * SIGHT_RADIUS_TILES;
145	}
146	
147	/**
148	 * Checks a map against §2 and §3: a compact sea, at most MAX_SEA_SIDE_TILES on a side; four small islands, each with
149	 * a dock; shoals; eight outer-sea spawn slots out of each other's engagement range; every dock and slot reachable by
150	 * sea; neighbouring islands 20–40 s apart and no useful crossing over 90 s at full speed; and a dock within 40 s of
151	 * every slot. No empty stretches: every navigable
152	 * tile lies within the sight radius of land, a shoal or a dock. Routes meet: the hub is open sea near the centre, and
153	 * every shortest route between docks on different islands crosses its disc (closing the disc lengthens or cuts
154	 * every one of them).
155	 */
156	export function validateSeaMap(map: SeaMapDefinition, tuning: ShipTuning, rules: SeaMapRules = sliceSeaRules): ValidationResult<SeaMapReport> {
157	  const issues: string[] = [];
158	  const { islands, docks, spawnSlots } = map;
159	  const tileCentre = Math.floor(map.subUnitsPerTile / 2);
160	
161	  if (tuning.hullHalfSize >= tileCentre) issues.push(`ship hull half-size ${tuning.hullHalfSize} does not fit inside one tile`);
162	  if (SIGHT_RADIUS_TILES <= ENGAGEMENT_RANGE_TILES) issues.push("the sight radius must be larger than the engagement range");
163	
164	  if (map.widthTiles > MAX_SEA_SIDE_TILES || map.heightTiles > MAX_SEA_SIDE_TILES) {
165	    issues.push(`${map.widthTiles} × ${map.heightTiles} tiles is larger than ${MAX_SEA_SIDE_TILES} × ${MAX_SEA_SIDE_TILES}`);
166	  }
167	  if (islands.length !== rules.islands) issues.push(`${islands.length} islands, not ${rules.islands}`);
168	  islands.forEach((island, index) => {
169	    if (island.widthTiles > MAX_ISLAND_SIDE_TILES || island.heightTiles > MAX_ISLAND_SIDE_TILES) {
170	      issues.push(`${island.name}: ${island.widthTiles} × ${island.heightTiles} tiles is not a small island`);
171	    }
172	    if (island.tileX < 0 || island.tileY < 0 || island.tileX + island.widthTiles > map.widthTiles || island.tileY + island.heightTiles > map.heightTiles) {
173	      issues.push(`${island.name}: outside the map`);
174	    }
175	    for (const other of islands.slice(index + 1)) {
176	      const apart =
177	        island.tileX + island.widthTiles <= other.tileX ||
178	        other.tileX + other.widthTiles <= island.tileX ||
179	        island.tileY + island.heightTiles <= other.tileY ||
180	        other.tileY + other.heightTiles <= island.tileY;
181	      if (!apart) issues.push(`${island.name} and ${other.name} overlap`);
182	    }
183	    if (!docks.some((dock) => dock.island === index)) issues.push(`${island.name}: no dock`);
184	  });
185	
186	  let landTiles = 0;
187	  let shoalTiles = 0;
188	  for (let tileY = 0; tileY < map.heightTiles; tileY++) {
189	    for (let tileX = 0; tileX < map.widthTiles; tileX++) {
190	      const kind = terrainAt(map, tileX, tileY);
191	      if (kind === Terrain.Shoal) shoalTiles++;
192	      if (kind !== Terrain.Land) continue;
193	      landTiles++;
194	      const owners = islands.filter((island) => insideIsland(island, tileX, tileY)).length;
195	      if (owners !== 1) issues.push(`land at ${tileX},${tileY} lies in ${owners} island rectangles, not one`);
196	    }
197	  }
198	  if (landTiles === 0) issues.push("no land");
199	  if (shoalTiles === 0) issues.push("no shoals");
200	
201	  const obstacleDistances = obstacleDistancesSquared(map);
202	  let largestObstacleDistanceSquared = 0;
203	  let empty = { count: 0, tileX: 0, tileY: 0 };
204	  obstacleDistances.forEach((distance, index) => {
205	    const tileX = index % map.widthTiles;
206	    const tileY = (index - tileX) / map.widthTiles;
207	    if (!isNavigable(map, tileX, tileY)) return;
208	    largestObstacleDistanceSquared = Math.max(largestObstacleDistanceSquared, distance);
209	    if (distance > SIGHT_RADIUS_TILES * SIGHT_RADIUS_TILES) empty = { count: empty.count + 1, tileX, tileY };
210	  });
211	  if (empty.count > 0) {
212	    issues.push(`${empty.count} sea tiles lie farther than ${SIGHT_RADIUS_TILES} tiles from any land, shoal or dock, such as ${empty.tileX},${empty.tileY}`);
213	  }
214	
215	  const { hub } = map;
216	  // Doubled coordinates keep the map's centre on an integer: the hub lies within half the sight radius of it.
217	  const offCentreX = 2 * hub.tileX + 1 - map.widthTiles;
218	  const offCentreY = 2 * hub.tileY + 1 - map.heightTiles;
219	  if (terrainAt(map, hub.tileX, hub.tileY) !== Terrain.Sea) issues.push(`the hub at ${hub.tileX},${hub.tileY} is not on open sea`);
220	  else if (offCentreX * offCentreX + offCentreY * offCentreY > SIGHT_RADIUS_TILES * SIGHT_RADIUS_TILES) {
221	    issues.push(`the hub at ${hub.tileX},${hub.tileY} is not near the map's centre`);
222	  }
223	
224	  const neighbours = (tileX: number, tileY: number) => [
225	    [tileX + 1, tileY],
226	    [tileX - 1, tileY],
227	    [tileX, tileY + 1],
228	    [tileX, tileY - 1],
229	  ] as const;
230	  for (const dock of docks) {
231	    const where = `dock at ${dock.tileX},${dock.tileY}`;
232	    const island = islands[dock.island];
233	    if (island === undefined) {
234	      issues.push(`${where}: outside every island rectangle`);
235	      continue;
236	    }
237	    const touches = (kind: Terrain) =>
238	      neighbours(dock.tileX, dock.tileY).some(([x, y]) => terrainAt(map, x, y) === kind && (kind !== Terrain.Land || insideIsland(island, x, y)));
239	    if (!touches(Terrain.Land)) issues.push(`${where}: not beside ${island.name}'s land`);
240	    if (!touches(Terrain.Sea)) issues.push(`${where}: no open sea beside it`);
241	  }
242	
243	  if (spawnSlots.length !== rules.spawnSlots) issues.push(`${spawnSlots.length} spawn slots, not ${rules.spawnSlots}`);
244	  const archipelago = boundsOf(islands);
245	  spawnSlots.forEach((slot, index) => {
246	    const where = `spawn slot ${index} at ${slot.tileX},${slot.tileY}`;
247	    if (terrainAt(map, slot.tileX, slot.tileY) !== Terrain.Sea) issues.push(`${where}: not on open sea`);
248	    if (
249	      archipelago !== undefined &&
250	      slot.tileX >= archipelago.minX &&
251	      slot.tileX <= archipelago.maxX &&
252	      slot.tileY >= archipelago.minY &&
253	      slot.tileY <= archipelago.maxY
254	    ) {
255	      issues.push(`${where}: inside the archipelago, not on the outer sea`);
256	    }
257	    spawnSlots.slice(index + 1).forEach((other, offset) => {
258	      const dx = other.tileX - slot.tileX;
259	      const dy = other.tileY - slot.tileY;
260	      if (dx * dx + dy * dy <= ENGAGEMENT_RANGE_TILES * ENGAGEMENT_RANGE_TILES) {
261	        issues.push(`${where}: within engagement range of slot ${index + 1 + offset}`);
262	      }
263	    });
264	  });
265	  if (issues.length > 0) return { ok: false, issues };
266	
267	  // Travel: one shortest-path search from every dock and spawn slot.
268	  const points: PointOfInterest[] = [
269	    ...docks.map((dock) => ({ label: `${islands[dock.island]!.name} ${dock.side} dock`, tileX: dock.tileX, tileY: dock.tileY })),
270	    ...spawnSlots.map((slot, index) => ({ label: `spawn slot ${index}`, tileX: slot.tileX, tileY: slot.tileY })),
271	  ];
272	  const costs = points.map((point) => seaPathCosts(map, point.tileX, point.tileY));
273	  const between = (from: number, to: number) => costs[from]![points[to]!.tileY * map.widthTiles + points[to]!.tileX]!;
274	
275	  const origin = docks.length;
276	  points.forEach((point, index) => {
277	    if (between(origin, index) === UNREACHABLE) issues.push(`${point.label} at ${point.tileX},${point.tileY}: not reachable by sea from spawn slot 0`);
278	  });
279	  if (issues.length > 0) return { ok: false, issues };
280	
281	  const nearestIsland = islands.map((island, index) => {
282	    let best = { nearest: "", cost: UNREACHABLE };
283	    docks.forEach((from, fromIndex) => {
284	      if (from.island !== index) return;
285	      docks.forEach((to, toIndex) => {
286	        if (to.island === index) return;
287	        const cost = between(fromIndex, toIndex);
288	        if (cost < best.cost) best = { nearest: islands[to.island]!.name, cost };
289	      });
290	    });
291	    return { island: island.name, nearest: best.nearest, seconds: travelSeconds(best.cost, tuning) };
292	  });
293	  for (const entry of nearestIsland) {
294	    if (entry.seconds < travelTargets.neighbourIslandMinSeconds || entry.seconds > travelTargets.neighbourIslandMaxSeconds) {
295	      issues.push(
296	        `${entry.island}: its nearest island, ${entry.nearest}, is ${entry.seconds} s away, outside ${travelTargets.neighbourIslandMinSeconds}–${travelTargets.neighbourIslandMaxSeconds} s`,
297	      );
298	    }
299	  }
300	
301	  let longest = { from: "", to: "", cost: 0 };
302	  points.forEach((from, fromIndex) => {
303	    points.forEach((to, toIndex) => {
304	      const cost = between(fromIndex, toIndex);
305	      if (cost > longest.cost) longest = { from: from.label, to: to.label, cost };
306	    });
307	  });
308	  const longestCrossing = { from: longest.from, to: longest.to, seconds: travelSeconds(longest.cost, tuning) };
309	  if (longestCrossing.seconds > travelTargets.longestCrossingMaxSeconds) {
310	    issues.push(`the crossing from ${longest.from} to ${longest.to} takes ${longestCrossing.seconds} s, over ${travelTargets.longestCrossingMaxSeconds} s`);
311	  }
312	
313	  const firstDock = spawnSlots.map((_, slot) => {
314	    let best = { dock: "", cost: UNREACHABLE };
315	    docks.forEach((_, dockIndex) => {
316	      const cost = between(origin + slot, dockIndex);
317	      if (cost < best.cost) best = { dock: points[dockIndex]!.label, cost };
318	    });
319	    return { slot, dock: best.dock, seconds: travelSeconds(best.cost, tuning) };
320	  });
321	  for (const entry of firstDock) {
322	    if (entry.seconds > travelTargets.firstDockMaxSeconds) {
323	      issues.push(`spawn slot ${entry.slot}: the nearest dock is ${entry.seconds} s away, over ${travelTargets.firstDockMaxSeconds} s`);
324	    }
325	  }
326	
327	  // Routes meet: with the hub's disc closed, every route between docks on different islands grows longer or is cut.
328	  const disc = new Uint8Array(map.widthTiles * map.heightTiles);
329	  disc.forEach((_, index) => {
330	    const tileX = index % map.widthTiles;
331	    disc[index] = inHubDisc(map, tileX, (index - tileX) / map.widthTiles) ? 1 : 0;
332	  });
333	  const hubApproach: { from: string; to: string; squaredTiles: number }[] = [];
334	  docks.forEach((from, fromIndex) => {
335	    const detour = seaPathCosts(map, from.tileX, from.tileY, disc);
336	    docks.forEach((to, toIndex) => {
337	      if (to.island === from.island) return;
338	      const direct = between(fromIndex, toIndex);
339	      if (detour[to.tileY * map.widthTiles + to.tileX]! <= direct) {
340	        issues.push(`${points[fromIndex]!.label} to ${points[toIndex]!.label}: a shortest route avoids the hub at ${hub.tileX},${hub.tileY}`);
341	      }
342	      if (toIndex > fromIndex) {
343	        const route = shortestRoute(map, costs[fromIndex]!, to.tileX, to.tileY);
344	        const squaredTiles = Math.min(...route.map(([x, y]) => (x - hub.tileX) * (x - hub.tileX) + (y - hub.tileY) * (y - hub.tileY)));
345	        hubApproach.push({ from: points[fromIndex]!.label, to: points[toIndex]!.label, squaredTiles });
346	      }
347	    });
348	  });
349	
350	  let openSea = 0;
351	  for (const kind of map.terrain) if (kind === Terrain.Sea) openSea++;
352	  const openSeaShare = openSea / map.terrain.length;
353	
354	  return issues.length > 0
355	    ? { ok: false, issues }
356	    : { ok: true, value: { nearestIsland, longestCrossing, firstDock, largestObstacleDistanceSquared, openSeaShare, hubApproach } };
357	}
358	
359	/**
360	 * One shortest route to a tile, as the tiles it visits from the target back to the search's start: each step goes to
361	 * the first neighbour (in a fixed order) whose cost plus the step equals the current cost.
362	 */
363	export function shortestRoute(map: SeaMapDefinition, costs: Float64Array, toX: number, toY: number): [number, number][] {
364	  const width = map.widthTiles;
365	  const step = octileStepCosts(map.subUnitsPerTile);
366	  const route: [number, number][] = [[toX, toY]];
367	  let [x, y] = [toX, toY];
368	  while (costs[y * width + x]! > 0 && costs[y * width + x]! < UNREACHABLE) {
369	    const cost = costs[y * width + x]!;
370	    let next: [number, number] | undefined;
371	    for (let dy = -1; dy <= 1 && next === undefined; dy++) {
372	      for (let dx = -1; dx <= 1 && next === undefined; dx++) {
373	        if (dx === 0 && dy === 0) continue;
374	        const nx = x + dx;
375	        const ny = y + dy;
376	        if (nx < 0 || ny < 0 || nx >= width || ny >= map.heightTiles) continue;
377	        const diagonal = dx !== 0 && dy !== 0;
378	        if (diagonal && (!isNavigable(map, x + dx, y) || !isNavigable(map, x, y + dy))) continue;
379	        if (costs[ny * width + nx]! + (diagonal ? step.diagonal : step.straight) === cost) next = [nx, ny];
380	      }
381	    }
382	    if (next === undefined) break;
383	    route.push(next);
384	    [x, y] = next;
385	  }
386	  return route;
387	}
388	
389	function boundsOf(islands: SeaMapDefinition["islands"]) {
390	  if (islands.length === 0) return undefined;
391	  return {
392	    minX: Math.min(...islands.map((island) => island.tileX)),
393	    minY: Math.min(...islands.map((island) => island.tileY)),
394	    maxX: Math.max(...islands.map((island) => island.tileX + island.widthTiles - 1)),
395	    maxY: Math.max(...islands.map((island) => island.tileY + island.heightTiles - 1)),
396	  };
397	}
398	
399	/** A binary min-heap of (cost, index) pairs for the path search. */
400	class MinHeap {
401	  private readonly costs: number[] = [];
402	  private readonly indexes: number[] = [];
403	
404	  get size(): number {
405	    return this.costs.length;
406	  }
407	
408	  push(cost: number, index: number): void {
409	    this.costs.push(cost);
410	    this.indexes.push(index);
411	    let child = this.costs.length - 1;
412	    while (child > 0) {
413	      const parent = (child - 1) >> 1;
414	      if (this.costs[parent]! <= cost) break;
415	      this.swap(child, parent);
416	      child = parent;
417	    }
418	  }
419	
420	  pop(): [number, number] {
421	    const top: [number, number] = [this.costs[0]!, this.indexes[0]!];
422	    const lastCost = this.costs.pop()!;
423	    const lastIndex = this.indexes.pop()!;
424	    if (this.costs.length > 0) {
425	      this.costs[0] = lastCost;
426	      this.indexes[0] = lastIndex;
427	      let parent = 0;
428	      for (;;) {
429	        const left = 2 * parent + 1;
430	        const right = left + 1;
431	        let smallest = parent;
432	        if (left < this.costs.length && this.costs[left]! < this.costs[smallest]!) smallest = left;
433	        if (right < this.costs.length && this.costs[right]! < this.costs[smallest]!) smallest = right;
434	        if (smallest === parent) break;
435	        this.swap(parent, smallest);
436	        parent = smallest;
437	      }
438	    }
439	    return top;
440	  }
441	
442	  private swap(a: number, b: number): void {
443	    [this.costs[a], this.costs[b]] = [this.costs[b]!, this.costs[a]!];
444	    [this.indexes[a], this.indexes[b]] = [this.indexes[b]!, this.indexes[a]!];
445	  }
446	}
