14	/**
15	 * The subset of Tiled's JSON map format (`.tmj`) that sea maps use. Anything outside it is refused, so a map that
16	 * relies on a feature the converter ignores cannot slip through.
17	 *
18	 * - An orthogonal, finite map of 24 × 24 pixel tiles (the size the game draws them at).
19	 * - One embedded tileset with `firstgid` 1 whose tiles each carry a `type` naming their terrain: `sea`, `land`,
20	 *   `shoal` or `dock`.
21	 * - A tile layer named `terrain` with its data as a plain array of global tile ids (Tiled's CSV encoding), no empty
22	 *   cells and no flip flags.
23	 * - An object layer named `objects` holding:
24	 *   - one rectangle of type `island` per island, named, with a string property `theme` (`tropical`, `volcanic`,
25	 *     `ruin` or `mist`), on tile boundaries, covering the island's land and docks;
26	 *   - one point of type `spawn` per spawn slot, with an int property `slot` (0 upwards, no gaps) and a string
27	 *     property `facing` (a compass direction such as `NE`);
28	 *   - exactly one point of type `hub`, without properties: the shared crossing near the centre that every route
29	 *     between islands passes (`validateSeaMap` checks it).
30	 *
31	 * Other layers, properties and object types are errors. Tiled keeps extra editor fields (`version`, `nextobjectid`,
32	 * `editorsettings` and so on); the schema ignores those.
33	 */
34	export const TILE_PIXELS = 24;
35	
36	const TERRAIN_TYPES = { sea: Terrain.Sea, land: Terrain.Land, shoal: Terrain.Shoal, dock: Terrain.Dock } as const;
37	
38	const propertySchema = z.discriminatedUnion("type", [
39	  z.object({ name: z.string(), type: z.literal("string"), value: z.string() }),
40	  z.object({ name: z.string(), type: z.literal("int"), value: z.int() }),
41	]);
42	
43	const tilesetSchema = z.object({
44	  firstgid: z.literal(1),
45	  name: z.string(),
46	  tilewidth: z.literal(TILE_PIXELS),
47	  tileheight: z.literal(TILE_PIXELS),
48	  tilecount: z.int().positive(),
49	  tiles: z.array(z.object({ id: z.int().nonnegative(), type: z.enum(["sea", "land", "shoal", "dock"]) })),
50	});
51	
52	const tileLayerSchema = z.object({
53	  type: z.literal("tilelayer"),
54	  name: z.literal("terrain"),
55	  width: z.int().positive(),
56	  height: z.int().positive(),
57	  x: z.literal(0),
58	  y: z.literal(0),
59	  encoding: z.literal("csv").optional(),
60	  compression: z.undefined().optional(),
61	  data: z.array(z.int().positive()),
62	});
63	
64	const objectSchema = z.object({
65	  id: z.int(),
66	  name: z.string(),
67	  type: z.enum(["island", "spawn", "hub"]),
68	  x: z.number(),
69	  y: z.number(),
70	  width: z.number().nonnegative(),
71	  height: z.number().nonnegative(),
72	  rotation: z.literal(0).optional(),
73	  point: z.boolean().optional(),
74	  properties: z.array(propertySchema).optional(),
75	});
76	
77	const objectLayerSchema = z.object({
78	  type: z.literal("objectgroup"),
79	  name: z.literal("objects"),
80	  objects: z.array(objectSchema),
81	});
82	
83	export const tiledMapSchema = z.object({
84	  type: z.literal("map"),
85	  orientation: z.literal("orthogonal"),
86	  infinite: z.literal(false),
87	  width: z.int().positive(),
88	  height: z.int().positive(),
89	  tilewidth: z.literal(TILE_PIXELS),
90	  tileheight: z.literal(TILE_PIXELS),
91	  tilesets: z.tuple([tilesetSchema]),
92	  layers: z.tuple([tileLayerSchema, objectLayerSchema]),
93	});
94	
95	export type TiledMap = z.infer<typeof tiledMapSchema>;
96	type TiledObject = z.infer<typeof objectSchema>;
97	
