1	/**
2	 * Converts the Tiled sea map (`assets/source/maps/slice-sea.tmj`, the subset documented in
3	 * `packages/content/src/tiledMap.ts`) into the typed module `packages/content/src/maps/sliceSea.ts`, after checking
4	 * it against the map validators. `--check` writes nothing and fails when the module is out of date. `--from-sketch`
5	 * first rewrites the `.tmj` from the ASCII sketch in `assets/source/maps/sliceSeaSketch.ts`.
6	 *
7	 *   npm run map:build -- --from-sketch   redraw the .tmj from the sketch, then convert and write
8	 *   npm run map:build                    convert and write
9	 *   npm run map:check                    compare only
10	 */
11	import { readFileSync, writeFileSync } from "node:fs";
12	import { fileURLToPath } from "node:url";
13	import { sliceSeaTmj } from "../assets/source/maps/sliceSeaSketch.js";
14	import { shipTuning } from "../packages/content/src/sailing.js";
15	import { createSeaMap } from "../packages/content/src/seaMap.js";
16	import { validateSeaMap } from "../packages/content/src/seaValidation.js";
17	import { convertTiledMap, formatSeaMapModule } from "../packages/content/src/tiledMap.js";
18	
19	const SLICE_SEA = {
20	  name: "slice-sea",
21	  source: "assets/source/maps/slice-sea.tmj",
22	  module: "packages/content/src/maps/sliceSea.ts",
23	  exportName: "sliceSeaSource",
24	} as const;
25	
26	const root = fileURLToPath(new URL("..", import.meta.url));
27	
28	function fail(lines: readonly string[]): never {
29	  for (const line of lines) console.error(`  ${line}`);
30	  process.exit(1);
31	}
32	
33	if (process.argv.includes("--from-sketch")) {
34	  const tmj = sliceSeaTmj();
35	  writeFileSync(`${root}${SLICE_SEA.source}`, tmj);
36	  const size = JSON.parse(tmj) as { width: number; height: number };
37	  console.log(`wrote ${SLICE_SEA.source} from the sketch: ${size.width} × ${size.height} tiles`);
38	}
39	
40	const converted = convertTiledMap(SLICE_SEA.name, JSON.parse(readFileSync(`${root}${SLICE_SEA.source}`, "utf8")));
41	if (!converted.ok) {
42	  console.error(`${SLICE_SEA.source} is outside the supported Tiled subset:`);
43	  fail(converted.issues);
44	}
45	const validated = validateSeaMap(createSeaMap(converted.value), shipTuning);
46	if (!validated.ok) {
47	  console.error(`${SLICE_SEA.source} fails the map validators:`);
48	  fail(validated.issues);
49	}
50	
51	const text = formatSeaMapModule(converted.value, SLICE_SEA.exportName, SLICE_SEA.source);
52	const target = `${root}${SLICE_SEA.module}`;
53	let current: string | undefined;
54	try {
55	  current = readFileSync(target, "utf8");
56	} catch {
57	  current = undefined;
58	}
59	
60	const report = validated.value;
61	console.log(`${SLICE_SEA.source}: ${converted.value.widthTiles} × ${converted.value.heightTiles} tiles`);
62	for (const entry of report.nearestIsland) console.log(`  ${entry.island} → ${entry.nearest}: ${entry.seconds} s`);
63	console.log(`  longest crossing: ${report.longestCrossing.from} → ${report.longestCrossing.to}: ${report.longestCrossing.seconds} s`);
64	console.log(`  first dock from a spawn slot: ${Math.max(...report.firstDock.map((entry) => entry.seconds))} s at most`);
65	const tiles = (squared: number) => Math.sqrt(squared).toFixed(1);
66	console.log(`  largest distance from open water to land, a shoal or a dock: ${tiles(report.largestObstacleDistanceSquared)} tiles`);
67	console.log(`  open sea: ${(report.openSeaShare * 100).toFixed(1)} % of the map`);
68	for (const entry of report.hubApproach) console.log(`  ${entry.from} → ${entry.to}: passes ${tiles(entry.squaredTiles)} tiles from the hub`);
69	
70	if (process.argv.includes("--check")) {
71	  if (current !== text) fail([`${SLICE_SEA.module} is out of date: run npm run map:build`]);
72	  console.log(`${SLICE_SEA.module} is up to date`);
73	} else if (current === text) {
74	  console.log(`${SLICE_SEA.module} is already up to date`);
75	} else {
76	  writeFileSync(target, text);
77	  console.log(`wrote ${SLICE_SEA.module}`);
78	}
